// Repo-side tests for pure whole-forest generated-outline artifact assembly.
//
// These are worker-authored unit tests over the batch operation only. They derive expectations from
// the accepted one-owner assembly and from the graph laws the batch must preserve, never from a
// recorded native answer. The independent acceptance oracle for this task is the ordinary repository
// test `tests/successor/outline_forest.mjs`, which rebuilds every owner's rows from the authored
// records, encodes them with the pinned LEAN dialect and counts the exact generated bytes with the
// retained application token oracle.
//
// This file is compiled as the test module of `src/bin/outline-forest-observe.rs`, which owns the
// `#[path]` declaration of the assembly for the forest surface, so `cargo test --locked` runs these
// tests without loading that module twice inside this crate.

use crate::outline_artifacts::{ForestRequest, Request, assemble, assemble_forest};
use serde_json::{Value, json};
use sha2::{Digest, Sha256};

const R: &str = "60000000-0000-4000-8000-000000000001";
const A: &str = "60000000-0000-4000-8000-000000000002";
const C: &str = "60000000-0000-4000-8000-000000000003";
const G: &str = "60000000-0000-4000-8000-000000000004";
const B: &str = "60000000-0000-4000-8000-000000000005";
const LEAF: &str = "60000000-0000-4000-8000-000000000006";
const OTHER: &str = "60000000-0000-4000-8000-000000000007";
const OTHER_CHILD: &str = "60000000-0000-4000-8000-000000000008";
const WIDE: &str = "60000000-0000-4000-8000-000000000009";
const W1: &str = "60000000-0000-4000-8000-00000000000a";
const W2: &str = "60000000-0000-4000-8000-00000000000b";
const W3: &str = "60000000-0000-4000-8000-00000000000c";
const NOWHERE: &str = "60000000-0000-4000-8000-0000000000ff";
const VERSION: &str = "forest-test-1";

/// The deep branch's authored warning text, holding every retention-sensitive character at once.
const WARNINGS: &str = "Unicode Ω漢字 plus \"quotes\", a \\ backslash and a\ttab.\nA second line.";

fn node(id: &str, name: &str, status: &str, children: &[&str]) -> Value {
    json!({"id": id, "name": name, "status": status, "micro_summary": format!("{name} summary."),
           "children": children})
}

/// One deep chain (R > A > G > LEAF), one wide branch (R > WIDE > W2/W1/W3), a resolved leaf and a
/// discarded leaf, an unrelated second tree, and every active status with its reason represented.
/// Supplied array order deliberately disagrees with authored child order, and `scope`/`ruled_out`
/// ride on one record so a test can prove they never reach a generated view anywhere in the batch.
fn forest() -> Value {
    let mut deep = node(G, "Deep", "deferred", &[LEAF]);
    deep["deferred_reason"] = json!("Resume after the index lands.");
    deep["warnings"] = json!(WARNINGS);
    let mut branch = node(C, "Discarded", "discarded", &[]);
    branch["discard_reason"] = json!("Rejected for a stated reason.\nKeep the LF.");
    let mut stuck = node(A, "Branch", "stuck", &[C, G]);
    stuck["blocker"] = json!("Wait for input.");
    stuck["scope"] = json!("NOT IN AN OUTLINE");
    stuck["ruled_out"] = json!("NOT IN THE CORE");
    let mut resolved = node(B, "Resolved", "resolved", &[]);
    resolved["crystallization"] = json!("Checked answer, kept out of every view.");
    let root = node(R, "Root", "in_progress", &[A, B, WIDE]);
    json!([
        node(LEAF, "Leaf", "not_examined", &[]),
        node(OTHER_CHILD, "Outer leaf", "in_progress", &[]),
        node(W3, "Wide three", "in_progress", &[]),
        stuck,
        node(W1, "Wide one", "in_progress", &[]),
        resolved,
        root,
        branch,
        node(WIDE, "Wide", "in_progress", &[W2, W1, W3]),
        deep,
        node(OTHER, "Other root", "in_progress", &[OTHER_CHILD]),
        node(W2, "Wide two", "in_progress", &[]),
    ])
}

/// The deep forest after one move: `LEAF` leaves `Deep` and lands under `Resolved`. Old and new
/// ancestors are both in the batch, so membership, order, counts and branch costs must all reprice.
fn moved() -> Value {
    let nodes = replace(
        &forest(),
        G,
        json!({"id": G, "name": "Deep", "status": "deferred", "micro_summary": "Deep summary.",
               "children": [], "deferred_reason": "Resume after the index lands.",
               "warnings": WARNINGS}),
    );
    replace(
        &nodes,
        B,
        json!({"id": B, "name": "Resolved", "status": "resolved", "micro_summary": "Resolved summary.",
               "children": [LEAF], "crystallization": "Checked answer, kept out of every view."}),
    )
}

/// Swaps one complete authored record in place, so a test never creates a duplicate identity or an
/// accidental partial record while expressing a single deliberate defect. The identity stays fixed;
/// `substitute` is the variant for defects that deliberately change the identity itself.
fn replace(nodes: &Value, id: &str, changed: Value) -> Value {
    substitute(
        nodes,
        id,
        {
            let mut patched = changed;
            patched["id"] = json!(id);
            patched
        },
    )
}

/// Swaps one record for another exactly as given, including a changed or malformed identity.
fn substitute(nodes: &Value, id: &str, changed: Value) -> Value {
    Value::Array(
        nodes
            .as_array()
            .expect("forest")
            .iter()
            .map(|item| {
                if item["id"] == id {
                    changed.clone()
                } else {
                    item.clone()
                }
            })
            .collect(),
    )
}

fn forest_request(source_version: &str, nodes: &Value) -> ForestRequest {
    serde_json::from_value(json!({"source_version": source_version, "nodes": nodes}))
        .expect("test forest request is a valid transport document")
}

fn batch(source_version: &str, nodes: &Value) -> Value {
    assemble_forest(&forest_request(source_version, nodes)).expect("test forest is valid")
}

fn rejection(source_version: &str, nodes: &Value) -> String {
    match assemble_forest(&forest_request(source_version, nodes)) {
        Ok(assembled) => panic!(
            "assembled an invalid forest into {} bytes",
            serde_json::to_string(&assembled).unwrap_or_default().len()
        ),
        Err(error) => error,
    }
}

fn transport_rejection(supplied: Value) -> String {
    match serde_json::from_value::<ForestRequest>(supplied.clone()) {
        Ok(_) => panic!("the transport accepted {supplied}"),
        Err(error) => error.to_string(),
    }
}

/// The accepted one-owner operation: the equality control for every batch bundle.
fn one_owner(owner: &str, source_version: &str, nodes: &Value) -> Value {
    let request: Request = serde_json::from_value(json!({
        "owner": owner, "source_version": source_version, "nodes": nodes,
    }))
    .expect("test one-owner request is valid");
    assemble(&request).expect("test forest is valid")
}

fn ids(nodes: &Value) -> Vec<String> {
    nodes
        .as_array()
        .expect("forest")
        .iter()
        .map(|item| item["id"].as_str().expect("node id").to_owned())
        .collect()
}

fn sorted(mut values: Vec<String>) -> Vec<String> {
    values.sort_unstable();
    values
}

fn children_of(nodes: &Value, id: &str) -> Vec<String> {
    nodes
        .as_array()
        .expect("forest")
        .iter()
        .find(|item| item["id"] == id)
        .unwrap_or_else(|| panic!("no supplied node {id}"))["children"]
        .as_array()
        .expect("children")
        .iter()
        .map(|child| child.as_str().expect("child id").to_owned())
        .collect()
}

fn owner_ids(assembled: &Value) -> Vec<String> {
    sorted(
        assembled["owners"]
            .as_object()
            .expect("owners")
            .keys()
            .cloned()
            .collect(),
    )
}

fn bundle(assembled: &Value, id: &str) -> Value {
    assembled["owners"]
        .get(id)
        .unwrap_or_else(|| panic!("the batch has no bundle for {id}"))
        .clone()
}

fn complete(assembled: &Value, name: &str) -> String {
    assembled[name]["text"]
        .as_str()
        .expect("view text")
        .to_owned()
}

fn lines(assembled: &Value, name: &str) -> Vec<String> {
    complete(assembled, name).lines().map(str::to_owned).collect()
}

/// Top-level document keys in rendered order; a two-space line is row data, not a key.
fn keys(assembled: &Value, name: &str) -> Vec<String> {
    lines(assembled, name)
        .iter()
        .filter(|line| !line.starts_with("  "))
        .map(|line| {
            line.split_once([':', '['])
                .map_or(line.as_str(), |(key, _)| key)
                .to_owned()
        })
        .collect()
}

fn rendered_ids(assembled: &Value, name: &str) -> Vec<String> {
    lines(assembled, name)
        .iter()
        .filter(|line| line.starts_with("  "))
        .map(|line| {
            line.split('\t')
                .find(|cell| cell.starts_with("60000000-"))
                .expect("id cell")
                .to_owned()
        })
        .collect()
}

fn row(assembled: &Value, name: &str, id: &str) -> Vec<String> {
    lines(assembled, name)
        .into_iter()
        .find(|line| line.starts_with("  ") && line.split('\t').any(|cell| cell == id))
        .unwrap_or_else(|| panic!("no rendered row for {id} in the {name} view"))
        .strip_prefix("  ")
        .expect("row indent")
        .split('\t')
        .map(str::to_owned)
        .collect()
}

/// The shared header columns of a rendered view. `~` marks the pinned semi-tabular dialect and is
/// not a column: per-row optional fields ride as trailing `key:value` cells instead.
fn columns(assembled: &Value, name: &str) -> Vec<String> {
    lines(assembled, name)
        .into_iter()
        .find(|line| line.starts_with("rows["))
        .expect("rows header")
        .split_once(':')
        .expect("header columns")
        .1
        .split('\t')
        .filter(|column| *column != "~")
        .map(str::to_owned)
        .collect()
}

fn tokens(assembled: &Value, name: &str) -> u64 {
    assembled[name]["meta"]["tokens"].as_u64().expect("tokens")
}

fn hash(assembled: &Value, name: &str) -> String {
    assembled[name]["meta"]["hash"]
        .as_str()
        .expect("hash")
        .to_owned()
}

fn branches(assembled: &Value) -> Vec<String> {
    sorted(
        assembled["shallow"]["meta"]["branch_full_tokens"]
            .as_object()
            .expect("branch map")
            .keys()
            .cloned()
            .collect(),
    )
}

fn cost_of(assembled: &Value, id: &str) -> u64 {
    assembled["shallow"]["meta"]["branch_full_tokens"][id]
        .as_u64()
        .expect("branch cost")
}

/// `(children, depth, descendants)` of one row, located through the rendered header rather than a
/// fixed offset: the accepted columns are lexicographic, so an active reason can precede them.
fn shape(assembled: &Value, name: &str, id: &str) -> [String; 3] {
    let header = columns(assembled, name);
    let cells = row(assembled, name, id);
    let at = |column: &str| {
        header
            .iter()
            .position(|found| found == column)
            .unwrap_or_else(|| panic!("the {name} view has no {column} column"))
    };
    [cells[at("children")].clone(), cells[at("depth")].clone(), cells[at("descendants")].clone()]
}

#[test]
fn every_supplied_node_gets_exactly_one_bundle_including_leaves_and_other_trees() {
    let nodes = forest();
    let assembled = batch(VERSION, &nodes);
    assert_eq!(
        owner_ids(&assembled),
        sorted(ids(&nodes)),
        "the batch is not exactly one bundle per supplied node"
    );
    assert_eq!(
        assembled["owners"].as_object().expect("owners").len(),
        nodes.as_array().expect("forest").len(),
        "a supplied node was silently dropped or duplicated"
    );
    for id in ids(&nodes) {
        let owned = bundle(&assembled, &id);
        let mut top: Vec<&str> = owned
            .as_object()
            .expect("bundle")
            .keys()
            .map(String::as_str)
            .collect();
        top.sort_unstable();
        assert_eq!(top, ["full", "shallow"], "the bundle for {id} is not exactly two views");
        for name in ["full", "shallow"] {
            let mut view: Vec<String> = owned[name].as_object().expect("view").keys().cloned().collect();
            view.sort_unstable();
            assert_eq!(view, ["meta", "text"], "the {name} view of {id} lost its sidecar shape");
        }
    }
}

#[test]
fn the_batch_is_exactly_the_supplied_version_and_the_owner_map() {
    let assembled = batch(VERSION, &forest());
    let mut top: Vec<&str> = assembled
        .as_object()
        .expect("object")
        .keys()
        .map(String::as_str)
        .collect();
    top.sort_unstable();
    assert_eq!(top, ["owners", "source_version"]);
    assert_eq!(assembled["source_version"], VERSION);
}

#[test]
fn each_bundle_equals_the_established_one_owner_assembly() {
    let nodes = forest();
    let assembled = batch(VERSION, &nodes);
    for id in ids(&nodes) {
        assert_eq!(
            bundle(&assembled, &id),
            one_owner(&id, VERSION, &nodes),
            "the batch bundle for {id} differs from the accepted one-owner assembly"
        );
    }
    // The same holds after a move, where membership and costs both change.
    let after = moved();
    let remapped = batch(VERSION, &after);
    for id in ids(&after) {
        assert_eq!(
            bundle(&remapped, &id),
            one_owner(&id, VERSION, &after),
            "the moved batch bundle for {id} differs from the one-owner assembly"
        );
    }
}

#[test]
fn the_supplied_version_is_exact_in_the_result_and_in_every_generated_view() {
    let nodes = forest();
    let numeric = batch("42", &nodes);
    assert_eq!(numeric["source_version"], "42");
    for id in ids(&nodes) {
        let owned = bundle(&numeric, &id);
        for name in ["full", "shallow"] {
            assert!(
                complete(&owned, name).contains("source_version:\"42\""),
                "{id} {name} did not quote the numeric-looking supplied version"
            );
        }
    }
    let plain = batch("v-next", &nodes);
    for id in ids(&nodes) {
        assert_ne!(
            hash(&bundle(&numeric, &id), "full"),
            hash(&bundle(&plain, &id), "full"),
            "a changed version must change {id}'s full bytes"
        );
        assert_ne!(
            hash(&bundle(&numeric, &id), "shallow"),
            hash(&bundle(&plain, &id), "shallow"),
            "a changed version must change {id}'s shallow bytes"
        );
    }
}

#[test]
fn coverage_membership_and_authored_order_survive_the_batch_for_every_owner() {
    let nodes = forest();
    let assembled = batch(VERSION, &nodes);
    assert_eq!(
        rendered_ids(&bundle(&assembled, R), "shallow"),
        [R, A, B, WIDE],
        "the root shallow view is not owner plus direct children in authored order"
    );
    assert_eq!(
        rendered_ids(&bundle(&assembled, R), "full"),
        [R, A, C, G, LEAF, B, WIDE, W2, W1, W3],
        "the root full view is not authored preorder"
    );
    assert_eq!(rendered_ids(&bundle(&assembled, A), "full"), [A, C, G, LEAF]);
    assert_eq!(rendered_ids(&bundle(&assembled, WIDE), "full"), [WIDE, W2, W1, W3]);
    assert_eq!(rendered_ids(&bundle(&assembled, OTHER), "full"), [OTHER, OTHER_CHILD]);
    assert_eq!(rendered_ids(&bundle(&assembled, LEAF), "full"), [LEAF]);
    // Nodes outside an owner's subtree never appear in that owner's views.
    let root_full = complete(&bundle(&assembled, R), "full");
    assert!(!root_full.contains(OTHER), "an unrelated root leaked into the owner's full view");
    let leaf_full = complete(&bundle(&assembled, LEAF), "full");
    assert!(!leaf_full.contains(G), "a leaf view grew its own ancestors");
    for id in ids(&nodes) {
        let owned = bundle(&assembled, &id);
        for name in ["full", "shallow"] {
            assert_eq!(
                keys(&owned, name),
                ["coverage", "path_template", "rows", "source_version", "source_version_scope", "token_encoding"],
                "{id} {name} keys are not canonical lexicographic with the rows block in place"
            );
            let mut ordered = columns(&owned, name);
            ordered.sort_unstable();
            assert_eq!(
                columns(&owned, name),
                ordered,
                "{id} {name} header columns are not lexicographic"
            );
            assert_eq!(owned[name]["meta"]["encoding"], "o200k_base");
        }
    }
    // Owner-relative depth and graph-wide counts hold for an internal and a leaf owner alike.
    assert_eq!(shape(&bundle(&assembled, R), "full", G), ["1", "2", "1"]);
    assert_eq!(shape(&bundle(&assembled, A), "full", G), ["1", "1", "1"]);
    assert_eq!(shape(&bundle(&assembled, R), "full", WIDE), ["3", "1", "3"]);
    assert_eq!(shape(&bundle(&assembled, LEAF), "full", LEAF), ["0", "0", "0"]);
    assert_eq!(shape(&bundle(&assembled, LEAF), "shallow", LEAF), ["0", "0", "0"]);
}

#[test]
fn every_leaf_full_cost_is_reproducible_inside_the_batch_itself() {
    let nodes = forest();
    let assembled = batch(VERSION, &nodes);
    for id in ids(&nodes) {
        let owned = bundle(&assembled, &id);
        assert_eq!(
            owned["shallow"]["meta"]["full_view_tokens"]
                .as_u64()
                .expect("owner cost"),
            tokens(&owned, "full"),
            "{id} does not report its own complete full-view cost"
        );
        assert_eq!(
            branches(&owned),
            sorted(children_of(&nodes, &id)),
            "{id} branch costs are not exactly its direct children"
        );
        for child in children_of(&nodes, &id) {
            assert_eq!(
                cost_of(&owned, &child),
                tokens(&bundle(&assembled, &child), "full"),
                "the branch cost for {child} is not its own bundle's full cost"
            );
        }
    }
    // A leaf owner is a one-row full artifact with an empty branch map, and still a real cost.
    let leaf = bundle(&assembled, LEAF);
    assert_eq!(rendered_ids(&leaf, "full"), [LEAF]);
    assert_eq!(
        leaf["shallow"]["meta"]["branch_full_tokens"]
            .as_object()
            .expect("empty branch map")
            .len(),
        0,
        "a leaf owner has no branch costs"
    );
    assert!(tokens(&leaf, "full") > 0, "a leaf full view cost nothing");
    // Every shallow row's own cost cell agrees with the sidecar and with that row's bundle.
    for id in ids(&nodes) {
        let owned = bundle(&assembled, &id);
        let at = columns(&owned, "shallow")
            .iter()
            .position(|column| column == "full_view_tokens")
            .expect("shallow cost column");
        for rendered in rendered_ids(&owned, "shallow") {
            let cell = row(&owned, "shallow", &rendered)[at]
                .parse::<u64>()
                .expect("numeric row cost");
            assert_eq!(
                cell,
                tokens(&bundle(&assembled, &rendered), "full"),
                "the shallow cost cell for {rendered} is not its own bundle's full cost"
            );
        }
    }
}

#[test]
fn every_status_and_active_reason_is_retained_in_its_own_bundle() {
    let assembled = batch(VERSION, &forest());
    let stuck = complete(&bundle(&assembled, A), "full");
    assert!(stuck.contains("Wait for input."), "the stuck blocker was lost");
    assert!(
        stuck.contains(r"Rejected for a stated reason.\nKeep the LF."),
        "the discarded reason was lost: {stuck}"
    );
    assert!(
        complete(&bundle(&assembled, G), "full").contains("Resume after the index lands."),
        "the deferred reason was lost"
    );
    assert!(complete(&bundle(&assembled, B), "full").contains("resolved"));
    assert!(complete(&bundle(&assembled, LEAF), "full").contains("not_examined"));
    assert!(complete(&bundle(&assembled, C), "full").contains("discarded"));
    // Active reasons only: text held under a reason key the node's own status does not carry stays
    // hidden in every bundle of the batch.
    let noisy = replace(
        &forest(),
        B,
        json!({"id": B, "name": "Resolved", "status": "resolved", "micro_summary": "Resolved summary.",
               "children": [], "crystallization": "Answered.", "blocker": "INACTIVE BLOCKER",
               "discard_reason": "INACTIVE DISCARD", "deferred_reason": "INACTIVE DEFERRED"}),
    );
    let rebuilt = batch(VERSION, &noisy);
    for id in ids(&noisy) {
        for name in ["full", "shallow"] {
            let text = complete(&bundle(&rebuilt, &id), name);
            for forbidden in ["INACTIVE BLOCKER", "INACTIVE DISCARD", "INACTIVE DEFERRED"] {
                assert!(
                    !text.contains(forbidden),
                    "{id} {name} emitted an inactive reason: {forbidden}"
                );
            }
        }
    }
}

#[test]
fn source_text_survives_every_bundle_without_leaking_authored_fields() {
    let nodes = forest();
    let assembled = batch(VERSION, &nodes);
    for id in ids(&nodes) {
        for name in ["full", "shallow"] {
            let text = complete(&bundle(&assembled, &id), name);
            assert!(!text.contains("NOT IN AN OUTLINE"), "{id} {name} leaked authored scope");
            assert!(!text.contains("NOT IN THE CORE"), "{id} {name} leaked ruled_out text");
            assert!(!text.contains("Checked answer"), "{id} {name} leaked a resolved body");
        }
    }
    // The pinned cell dialect doubles quotes, escapes a backslash and an LF, and keeps a real tab.
    let warned = complete(&bundle(&assembled, G), "full");
    assert!(warned.contains("Ω漢字"), "Unicode was not preserved: {warned}");
    assert!(warned.contains("\"\"quotes\"\""), "quotes were not doubled: {warned}");
    assert!(warned.contains(r"a \\ backslash"), "a backslash was not escaped: {warned}");
    assert!(warned.contains("a\ttab"), "a literal tab did not survive: {warned}");
    assert!(
        warned.contains(r"\nA second line."),
        "a multiline warning was not escaped losslessly: {warned}"
    );
    let subtree = complete(&bundle(&assembled, A), "full");
    assert!(
        subtree.contains(r"Rejected for a stated reason.\nKeep the LF."),
        "a multiline reason was not escaped losslessly: {subtree}"
    );
    // Padded authored text keeps its outer whitespace exactly in every bundle that shows it.
    let padded = batch(
        VERSION,
        &replace(
            &forest(),
            LEAF,
            json!({"id": LEAF, "name": "Leaf", "status": "not_examined",
                   "micro_summary": "  padded Ω  ", "children": []}),
        ),
    );
    assert!(
        complete(&bundle(&padded, R), "full").contains("\"  padded Ω  \""),
        "outer whitespace was not preserved"
    );
}

#[test]
fn metadata_is_the_exact_hash_and_non_self_referential_count_of_every_bundle() {
    let nodes = forest();
    let assembled = batch(VERSION, &nodes);
    for id in ids(&nodes) {
        let owned = bundle(&assembled, &id);
        for name in ["full", "shallow"] {
            let mut meta: Vec<String> = owned[name]["meta"]
                .as_object()
                .expect("meta")
                .keys()
                .cloned()
                .collect();
            meta.sort_unstable();
            let expected: Vec<&str> = if name == "full" {
                vec!["encoding", "hash", "tokens"]
            } else {
                vec!["branch_full_tokens", "encoding", "full_view_tokens", "hash", "tokens"]
            };
            assert_eq!(meta, expected, "{id} {name} metadata keys are not the established sidecar");
            let text = complete(&owned, name);
            assert!(text.ends_with('\n'), "{id} {name} lacks its final LF");
            assert!(!text.ends_with("\n\n"), "{id} {name} has more than one final LF");
            assert_eq!(
                hash(&owned, name),
                format!("{:x}", Sha256::digest(text.as_bytes())),
                "{id} {name} hash is not SHA-256 of the complete text"
            );
            assert!(tokens(&owned, name) > 0, "{id} {name} counted zero tokens");
            assert!(
                !text.contains(&hash(&owned, name)),
                "{id} counted text contains its own {name} hash"
            );
            assert!(
                !text.contains("branch_full_tokens"),
                "a sidecar field entered {id}'s counted {name} text"
            );
            if name == "full" {
                assert!(
                    !text.contains("full_view_tokens"),
                    "a cost column entered {id}'s counted full text"
                );
            }
        }
        assert_ne!(
            tokens(&owned, "full"),
            tokens(&owned, "shallow"),
            "{id} two different complete texts share one count"
        );
    }
}

#[test]
fn a_moved_subtree_reprices_the_old_and_new_ancestors_in_one_batch() {
    let after = moved();
    let assembled = batch(VERSION, &after);
    // Old ancestor: LEAF is gone from its membership and its branch costs.
    let deep = bundle(&assembled, G);
    assert_eq!(rendered_ids(&deep, "full"), [G], "the moved subtree stayed under its old ancestor");
    assert_eq!(rendered_ids(&deep, "shallow"), [G]);
    assert!(branches(&deep).is_empty(), "the old ancestor still bills the moved node as a branch");
    assert_eq!(shape(&deep, "full", G), ["0", "0", "0"], "the old ancestor kept a stale count");
    // New ancestor: the moved node appears at the right depth and order and is billed as a branch.
    let resolved = bundle(&assembled, B);
    assert_eq!(rendered_ids(&resolved, "full"), [B, LEAF], "the moved subtree is not under its parent");
    assert_eq!(shape(&resolved, "full", LEAF), ["0", "1", "0"], "moved depth is stale");
    assert_eq!(branches(&resolved), vec![LEAF.to_owned()]);
    assert_eq!(
        cost_of(&resolved, LEAF),
        tokens(&bundle(&assembled, LEAF), "full"),
        "the new ancestor's branch cost is not the moved node's own full cost"
    );
    // The transitive root sees the move too.
    let root = bundle(&assembled, R);
    assert_eq!(
        rendered_ids(&root, "full"),
        [R, A, C, G, B, LEAF, WIDE, W2, W1, W3],
        "the root preorder did not follow the move"
    );
    assert_eq!(
        shape(&root, "full", B),
        ["1", "1", "1"],
        "the root's counts for the new parent are stale"
    );
    // Every supplied node still gets exactly one bundle after the move.
    assert_eq!(owner_ids(&assembled), sorted(ids(&after)));
}

#[test]
fn an_empty_forest_is_an_empty_owner_set_at_the_supplied_version() {
    let assembled = batch("empty-v1", &json!([]));
    assert_eq!(assembled["source_version"], "empty-v1");
    assert_eq!(assembled["owners"], json!({}));
    assert_eq!(assembled["owners"].as_object().expect("owners").len(), 0);
}

#[test]
fn a_blank_supplied_version_is_rejected_before_any_bundle_exists() {
    for version in ["", " \t\n"] {
        assert!(
            rejection(version, &forest()).contains("nonblank supplied source_version"),
            "a non-empty forest accepted the blank version {version:?}"
        );
        // The empty forest has no owner whose projection could catch it, so the batch must.
        assert!(
            rejection(version, &json!([])).contains("nonblank supplied source_version"),
            "an empty forest accepted the blank version {version:?}"
        );
    }
}

#[test]
fn the_transport_accepts_only_the_two_named_keys_and_the_right_types() {
    assert_eq!(
        transport_rejection(json!({"nodes": []})),
        "missing field `source_version`"
    );
    assert_eq!(
        transport_rejection(json!({"source_version": VERSION})),
        "missing field `nodes`"
    );
    for (supplied, key) in [
        (
            json!({"source_version": VERSION, "nodes": [], "owner": R}),
            "unknown field `owner`",
        ),
        (
            json!({"source_version": VERSION, "nodes": [], "coverage": "full"}),
            "unknown field `coverage`",
        ),
        (
            json!({"source_version": VERSION, "nodes": [], "sourceVersion": VERSION}),
            "unknown field `sourceVersion`",
        ),
    ] {
        assert!(
            transport_rejection(supplied).contains(key),
            "the transport accepted an extra key instead of {key}"
        );
    }
    for supplied in [
        json!({"source_version": 42, "nodes": []}),
        json!({"source_version": null, "nodes": []}),
        json!({"source_version": VERSION, "nodes": {}}),
        json!({"source_version": VERSION, "nodes": null}),
        Value::String("nope".to_owned()),
        json!(["source_version", VERSION]),
    ] {
        assert!(
            transport_rejection(supplied).contains("invalid type"),
            "the transport accepted a wrongly typed document"
        );
    }
    // `nodes` is deliberately raw logical records at the transport edge, so a record that is not an
    // object passes the shape-free transport and must be refused by the batch itself, whole.
    assert!(
        rejection(VERSION, &json!([R])).contains("malformed logical node records"),
        "a bare string in `nodes` reached the bundle loop"
    );
}

#[test]
fn one_invalid_node_rejects_the_whole_batch_without_a_partial_artifact_set() {
    // Each defective record sits where several owners never display it, and the batch still refuses
    // to emit any artifact set at all.
    let defective = [
        (
            "blank authored summary",
            replace(
                &forest(),
                OTHER_CHILD,
                json!({"id": OTHER_CHILD, "name": "Outer leaf", "status": "in_progress",
                       "micro_summary": " ", "children": []}),
            ),
        ),
        (
            "whitespace authored summary",
            replace(
                &forest(),
                OTHER_CHILD,
                json!({"id": OTHER_CHILD, "name": "Outer leaf", "status": "in_progress",
                       "micro_summary": "\t", "children": []}),
            ),
        ),
        (
            "blank discard reason",
            replace(
                &forest(),
                C,
                json!({"id": C, "name": "Discarded", "status": "discarded",
                       "micro_summary": "Discarded summary.", "children": [], "discard_reason": " "}),
            ),
        ),
        (
            "blank resolved crystallization",
            replace(
                &forest(),
                B,
                json!({"id": B, "name": "Resolved", "status": "resolved",
                       "micro_summary": "Resolved summary.", "children": [],
                       "crystallization": ""}),
            ),
        ),
    ];
    for (label, nodes) in defective {
        let error = rejection(VERSION, &nodes);
        match label {
            "blank authored summary" | "whitespace authored summary" => {
                assert!(error.contains("blank authored summary"), "{label}: {error}")
            }
            "blank discard reason" => assert!(error.contains("discard_reason"), "{label}: {error}"),
            _ => assert!(
                error.contains("resolved with blank crystallization"),
                "{label}: {error}"
            ),
        }
    }
    // A record that is not a node at all is refused before the first bundle is built.
    assert!(
        rejection(VERSION, &replace(&forest(), LEAF, json!({"id": LEAF})))
            .contains("malformed logical node records"),
        "a non-record was accepted"
    );
}

#[test]
fn invalid_store_identity_and_hierarchy_are_rejected_not_repaired() {
    assert!(
        rejection(
            VERSION,
            &replace(&forest(), OTHER, node(OTHER, "Other root", "in_progress", &[OTHER]))
        )
        .contains("cycle"),
        "a self-parenting root was accepted"
    );
    assert!(
        rejection(
            VERSION,
            &replace(&forest(), OTHER_CHILD, node(OTHER_CHILD, "Outer leaf", "in_progress", &[OTHER]))
        )
        .contains("cycle"),
        "a two-node cycle was accepted"
    );
    assert!(
        rejection(
            VERSION,
            &replace(&forest(), OTHER, node(OTHER, "Other root", "in_progress", &[B]))
        )
        .contains("more than one parent"),
        "a doubly owned child was accepted"
    );
    assert!(
        rejection(
            VERSION,
            &replace(&forest(), OTHER, node(OTHER, "Other root", "in_progress", &[NOWHERE]))
        )
        .contains("missing child"),
        "a missing child was accepted"
    );
    assert!(
        rejection(
            VERSION,
            &replace(&forest(), OTHER, node(OTHER, "Other root", "in_progress", &[OTHER_CHILD, OTHER_CHILD]))
        )
        .contains("twice"),
        "a duplicated child entry was accepted"
    );
    assert!(
        rejection(VERSION, &{
            let mut nodes = forest().as_array().expect("forest").clone();
            nodes.push(node(W1, "Wide one again", "in_progress", &[]));
            Value::Array(nodes)
        })
        .contains("duplicate node id"),
        "a duplicate identity was accepted"
    );
    assert!(
        rejection(
            VERSION,
            &substitute(&forest(), LEAF, node("not-a-uuid", "Leaf", "in_progress", &[]))
        )
        .contains("malformed node id"),
        "a malformed identity was accepted"
    );
    assert!(
        rejection(
            VERSION,
            &replace(
                &forest(),
                G,
                json!({"id": G, "name": "Deep", "status": "deferred", "micro_summary": "Deep summary.",
                       "children": ["not-a-uuid"], "deferred_reason": "Resume after the index lands."}),
            )
        )
        .contains("malformed child id"),
        "a malformed child reference was accepted"
    );
    assert!(
        rejection(
            VERSION,
            &replace(&forest(), LEAF, json!({"id": LEAF, "name": "Leaf", "status": "in_progress",
                                             "micro_summary": "Leaf summary."}))
        )
        .contains("missing field `children`"),
        "a record without children was accepted"
    );
    assert!(
        rejection(
            VERSION,
            &replace(&forest(), LEAF, json!({"id": LEAF, "name": "Leaf", "status": "unknown_state",
                                             "micro_summary": "Leaf summary.", "children": []}))
        )
        .contains("unknown variant"),
        "an unknown status was accepted"
    );
}

#[test]
fn the_batch_is_pure_text_and_costs_with_no_file_or_freshness_surface() {
    let assembled = batch(VERSION, &forest());
    let encoded = serde_json::to_string(&assembled).expect("serialisable");
    for forbidden in [
        "sqlite",
        "stale",
        "current",
        "meta.json",
        "outline.lean",
        "refresh",
        "path\":",
        "ruled_out",
    ] {
        assert!(!encoded.contains(forbidden), "the forest result leaked {forbidden:?}");
    }
    assert!(encoded.contains("nodes/{id}/node.md"), "the canonical path template is missing");
    assert!(encoded.contains("o200k_base"), "the token encoding identity is missing");
}
